// Read-only telemetry plus the existing explicit HBM offset controls.
// No GPU reset, driver reload, Xorg, or raw-register access is used.
use std::{env, ffi::{CStr,CString}, os::raw::{c_char,c_int,c_uint,c_ulong,c_ulonglong}};
type Device=*mut std::ffi::c_void; type R=c_int;
const OK:R=0; const CLOCK_MEM:c_uint=2; const TEMP_GPU:c_uint=0; const MEM_TEMP_FIELD:c_uint=82; const MEM_MAX_THRESHOLD:c_uint=2;
const PERSIST_ENABLED:c_uint=1;
#[repr(C)] struct Util { gpu:c_uint, memory:c_uint }
#[repr(C)] struct Mem { total:c_ulonglong, free:c_ulonglong, used:c_ulonglong }
