 fn nvmlDeviceGetClockInfo(device:Device, clock:c_uint, mhz:*mut c_uint)->R; fn nvmlDeviceGetMaxClockInfo(device:Device,clock:c_uint,mhz:*mut c_uint)->R; fn nvmlDeviceGetTemperature(device:Device, sensor:c_uint, temp:*mut c_uint)->R;
