 fn nvmlDeviceGetCurrPcieLinkGeneration(device:Device, generation:*mut c_uint)->R; fn nvmlDeviceGetCurrPcieLinkWidth(device:Device, width:*mut c_uint)->R; fn nvmlDeviceGetMaxPcieLinkGeneration(device:Device,generation:*mut c_uint)->R; fn nvmlDeviceGetMaxPcieLinkWidth(device:Device,width:*mut c_uint)->R; fn nvmlDeviceGetPcieThroughput(device:Device,counter:c_uint,kb:*mut c_uint)->R; fn nvmlDeviceGetPcieReplayCounter(device:Device,count:*mut c_uint)->R;
 fn nvmlDeviceGetBAR1MemoryInfo(device:Device,bar:*mut Bar1)->R; fn nvmlDeviceGetNumGpuCores(device:Device,cores:*mut c_uint)->R; fn nvmlDeviceGetMemoryBusWidth(device:Device,width:*mut c_uint)->R; fn nvmlDeviceGetCudaComputeCapability(device:Device,major:*mut c_int,minor:*mut c_int)->R; fn nvmlDeviceGetArchitecture(device:Device,arch:*mut c_uint)->R;
