fn err(r:R)->String { unsafe { CStr::from_ptr(nvmlErrorString(r)).to_string_lossy().into_owned() } }
fn strget(f:unsafe extern "C" fn(Device,*mut c_char,c_uint)->R,d:Device)->String { let mut b=[0i8;96]; unsafe{f(d,b.as_mut_ptr(),96)}; unsafe{CStr::from_ptr(b.as_ptr()).to_string_lossy().into_owned()} }
fn dev(i:c_uint)->Device { let mut d=std::ptr::null_mut(); let r=unsafe{nvmlDeviceGetHandleByIndex_v2(i,&mut d)}; if r!=OK {panic!("NVML device {i}: {}",err(r))};d }
fn uuid_dev(s:&str)->Device { let c=CString::new(s).expect("UUID NUL"); let mut d=std::ptr::null_mut(); let r=unsafe{nvmlDeviceGetHandleByUUID(c.as_ptr(),&mut d)}; if r!=OK {panic!("NVML UUID: {}",err(r))};d }
fn raw_fields(d:Device)->String { let mut out=Vec::new(); for id in 1..=199u32 { let mut f=Field{fieldId:id,scopeId:0,timestamp:i64::MIN,latencyUsec:i64::MIN,valueType:6,nvmlReturn:999,value:FieldValue{ullVal:0xdeadbeefdeadbeef}}; let outer=unsafe{nvmlDeviceGetFieldValues(d,1,&mut f)}; let unchanged=f.nvmlReturn==999 && f.valueType==6 && f.timestamp==i64::MIN; let (state,value)=if outer!=OK {("error",format!("null"))} else if unchanged {("unreturned",format!("null"))} else if f.nvmlReturn!=OK {("unsupported",format!("null"))} else { let v=unsafe{match f.valueType {0=>format!("{}",f.value.dVal),1=>format!("{}",f.value.uiVal),2=>format!("\"{}\"",f.value.ulVal),3=>format!("\"{}\"",f.value.ullVal),4=>format!("\"{}\"",f.value.sllVal),5=>format!("{}",f.value.siVal),_=>"null".into()}}; ("driver_reported",v) }; out.push(format!("{{\"id\":{id},\"value\":{value},\"valueType\":{},\"nvmlReturn\":{},\"outerReturn\":{outer},\"reliability\":\"{state}\",\"timestampUs\":{},\"latencyUs\":{}}}",f.valueType,f.nvmlReturn,if f.timestamp==i64::MIN{"null".to_string()}else{format!("\"{}\"",f.timestamp)},if f.latencyUsec==i64::MIN{"null".to_string()}else{format!("\"{}\"",f.latencyUsec)})); } out.join(",") }
fn sample_stream(d:Device,typ:c_int)->String { let mut vt=6;let mut count=0;let probe=unsafe{nvmlDeviceGetSamples(d,typ,0,&mut vt,&mut count,std::ptr::null_mut())}; if probe!=OK {return format!("{{\"type\":{typ},\"probeReturn\":{probe},\"samples\":[]}}")}; if count>1000000{return format!("{{\"type\":{typ},\"probeReturn\":{probe},\"error\":\"sample_count_cap\",\"samples\":[]}}")};let mut v:Vec<Sample>=Vec::with_capacity(count as usize);let read=unsafe{nvmlDeviceGetSamples(d,typ,0,&mut vt,&mut count,v.as_mut_ptr())};unsafe{v.set_len(if read==OK{count as usize}else{0})};let values=v.iter().map(|s|{let value=unsafe{match vt {0=>format!("{}",s.value.dVal),1=>format!("{}",s.value.uiVal),2=>format!("\"{}\"",s.value.ulVal),3=>format!("\"{}\"",s.value.ullVal),4=>format!("\"{}\"",s.value.sllVal),5=>format!("{}",s.value.siVal),_=>"null".into()}};format!("{{\"timestampUs\":\"{}\",\"value\":{value}}}",s.timestamp)}).collect::<Vec<_>>().join(",");format!("{{\"type\":{typ},\"probeReturn\":{probe},\"readReturn\":{read},\"valueType\":{vt},\"samples\":[{values}]}}")}
fn processes(d:Device,graphics:bool)->String { let mut count=0;let probe=unsafe{if graphics{nvmlDeviceGetGraphicsRunningProcesses_v3(d,&mut count,std::ptr::null_mut())}else{nvmlDeviceGetComputeRunningProcesses_v3(d,&mut count,std::ptr::null_mut())}};if probe!=OK && probe!=7{return format!("{{\"probeReturn\":{probe},\"entries\":[]}}")};if count>1000000{return "{\"error\":\"process_count_cap\",\"entries\":[]}".into()};let mut v:Vec<ProcessInfo>=Vec::with_capacity(count as usize+4);let mut cap=v.capacity() as c_uint;let read=unsafe{if graphics{nvmlDeviceGetGraphicsRunningProcesses_v3(d,&mut cap,v.as_mut_ptr())}else{nvmlDeviceGetComputeRunningProcesses_v3(d,&mut cap,v.as_mut_ptr())}};unsafe{v.set_len(if read==OK{cap as usize}else{0})};let entries=v.iter().map(|p|format!("{{\"pid\":{},\"usedGpuMemoryBytes\":{},\"gpuInstanceId\":{},\"computeInstanceId\":{}}}",p.pid,if p.usedGpuMemory==u64::MAX{"null".into()}else{format!("\"{}\"",p.usedGpuMemory)},if p.gpuInstanceId==u32::MAX{"null".into()}else{p.gpuInstanceId.to_string()},if p.computeInstanceId==u32::MAX{"null".into()}else{p.computeInstanceId.to_string()})).collect::<Vec<_>>().join(",");format!("{{\"probeReturn\":{probe},\"readReturn\":{read},\"entries\":[{entries}]}}")}
fn main(){ let a:Vec<String>=env::args().collect(); let r=unsafe{nvmlInit_v2()};if r!=OK{panic!("NVML init: {}",err(r))}; let mut n=0;unsafe{nvmlDeviceGetCount_v2(&mut n)};
 let cmd=a.get(1).map(String::as_str).unwrap_or("");
 if matches!(cmd,"set-power-limit"|"set-core-offset"|"set-hbm-offset") { let u=a.iter().position(|x|x=="--uuid").and_then(|p|a.get(p+1)).expect("--uuid GPU-..."); let value_flag=if cmd=="set-power-limit"{"--watts"}else{"--raw-offset"}; let v=a.iter().position(|x|x==value_flag).and_then(|p|a.get(p+1)).expect("missing control value").parse::<i64>().expect("integer"); let d=uuid_dev(u); let mut before_i=0; let mut before_w=0; let mut lo=0; let mut hi=0;
   unsafe { match cmd { "set-power-limit"=>{let cr=nvmlDeviceGetPowerManagementLimitConstraints(d,&mut lo,&mut hi); if cr!=OK {panic!("power constraints: {}",err(cr))}; if v<0 || (v as u64)*1000 < lo as u64 || (v as u64)*1000 > hi as u64 {panic!("watts outside {}..{}",lo/1000,hi/1000)}; nvmlDeviceGetPowerManagementLimit(d,&mut before_w);}, "set-core-offset"=>{nvmlDeviceGetGpcClkVfOffset(d,&mut before_i);}, _=>{nvmlDeviceGetMemClkVfOffset(d,&mut before_i);} } }
   let before=if cmd=="set-power-limit"{before_w as i64/1000}else{before_i as i64};
   if !a.iter().any(|x|x=="--apply") { println!("{{\"command\":\"{cmd}\",\"uuid\":\"{u}\",\"previous\":{before},\"requested\":{v},\"dryRun\":true,\"requires\":\"--apply\"}}") }
   else { let (r,readback)=unsafe{match cmd {"set-power-limit"=>{let r=nvmlDeviceSetPowerManagementLimit(d,(v*1000) as c_uint);let mut got=0;let rr=nvmlDeviceGetPowerManagementLimit(d,&mut got);if rr!=OK {(r,-1)}else{(r,got as i64/1000)}},"set-core-offset"=>{let r=nvmlDeviceSetGpcClkVfOffset(d,v as c_int);let mut got=0;let rr=nvmlDeviceGetGpcClkVfOffset(d,&mut got);if rr!=OK {(r,-1)}else{(r,got as i64)}},_=>{let r=nvmlDeviceSetMemClkVfOffset(d,v as c_int);let mut got=0;let rr=nvmlDeviceGetMemClkVfOffset(d,&mut got);if rr!=OK {(r,-1)}else{(r,got as i64)}}}};println!("{{\"command\":\"{cmd}\",\"uuid\":\"{u}\",\"previous\":{before},\"requested\":{v},\"readback\":{readback},\"nvmlReturn\":{r},\"result\":\"{}\"}}",if r==OK{"success"}else{"error"}); }
 } else if cmd=="fields" { let mut out=Vec::new(); for i in 0..n { let d=dev(i); out.push(format!("{{\"index\":{i},\"uuid\":\"{}\",\"rawFieldValues\":[{}]}}",strget(nvmlDeviceGetUUID,d),raw_fields(d))); } println!("{{\"schemaVersion\":2,\"gpus\":[{}]}}",out.join(","));
 } else if cmd=="samples" { let mut out=Vec::new(); for i in 0..n { let d=dev(i);let rows=(0..=9).map(|t|sample_stream(d,t)).collect::<Vec<_>>().join(",");out.push(format!("{{\"index\":{i},\"uuid\":\"{}\",\"sampleStreams\":[{rows}]}}",strget(nvmlDeviceGetUUID,d)));}println!("{{\"schemaVersion\":2,\"gpus\":[{}]}}",out.join(","));
 } else if cmd=="processes" { let mut out=Vec::new();for i in 0..n {let d=dev(i);out.push(format!("{{\"index\":{i},\"uuid\":\"{}\",\"compute\":{},\"graphics\":{}}}",strget(nvmlDeviceGetUUID,d),processes(d,false),processes(d,true)));}println!("{{\"schemaVersion\":2,\"gpus\":[{}]}}",out.join(","));
 } else if cmd=="telemetry" { let json=a.iter().any(|x|x=="--json"); let mut out=Vec::new(); for i in 0..n {let d=dev(i); let mut mo=0;let mut go=0;let(mut gmin,mut gmax)=(0,0);let(mut mm,mut mx)=(0,0);let(mut c0,mut c1,mut c2,mut c3)=(0,0,0,0);let(mut x0,mut x1,mut x2,mut x3)=(0,0,0,0);let(mut tg,mut hm)=(0,0);let(mut tsh,mut tsl,mut tmax)=(0,0,0);let(mut pw,mut pl,mut pd,mut pe,mut plo,mut phi)=(0,0,0,0,0,0);let mut energy=0;let mut u=Util{gpu:0,memory:0};let mut m=Mem{total:0,free:0,used:0};let mut b=Bar1{total:0,free:0,used:0};let(mut ps,mut th,mut thsup)=(0,0,0);let(mut pg,mut px,mut pgm,mut pxm,mut ptx,mut prx,mut replay)=(0,0,0,0,0,0,0);let(mut cores,mut bus,mut arch)=(0,0,0);let(mut ccmaj,mut ccmin)=(0,0);let mut field=Field{fieldId:MEM_TEMP_FIELD,scopeId:0,timestamp:0,latencyUsec:0,valueType:0,nvmlReturn:-1,value:FieldValue{ullVal:0}};
 unsafe { nvmlDeviceGetMemClkVfOffset(d,&mut mo);nvmlDeviceGetGpcClkVfOffset(d,&mut go);nvmlDeviceGetGpcClkMinMaxVfOffset(d,&mut gmin,&mut gmax);let mem_range=nvmlDeviceGetMemClkMinMaxVfOffset(d,&mut mm,&mut mx);nvmlDeviceGetClockInfo(d,0,&mut c0);nvmlDeviceGetClockInfo(d,1,&mut c1);nvmlDeviceGetClockInfo(d,2,&mut c2);nvmlDeviceGetClockInfo(d,3,&mut c3);nvmlDeviceGetMaxClockInfo(d,0,&mut x0);nvmlDeviceGetMaxClockInfo(d,1,&mut x1);nvmlDeviceGetMaxClockInfo(d,2,&mut x2);nvmlDeviceGetMaxClockInfo(d,3,&mut x3);nvmlDeviceGetTemperature(d,TEMP_GPU,&mut tg);nvmlDeviceGetTemperatureThreshold(d,0,&mut tsh);nvmlDeviceGetTemperatureThreshold(d,1,&mut tsl);nvmlDeviceGetTemperatureThreshold(d,MEM_MAX_THRESHOLD,&mut hm);nvmlDeviceGetTemperatureThreshold(d,3,&mut tmax);nvmlDeviceGetFieldValues(d,1,&mut field);nvmlDeviceGetPowerUsage(d,&mut pw);nvmlDeviceGetPowerManagementLimit(d,&mut pl);nvmlDeviceGetPowerManagementDefaultLimit(d,&mut pd);nvmlDeviceGetEnforcedPowerLimit(d,&mut pe);nvmlDeviceGetPowerManagementLimitConstraints(d,&mut plo,&mut phi);nvmlDeviceGetTotalEnergyConsumption(d,&mut energy);nvmlDeviceGetUtilizationRates(d,&mut u);nvmlDeviceGetMemoryInfo(d,&mut m);nvmlDeviceGetBAR1MemoryInfo(d,&mut b);nvmlDeviceGetPerformanceState(d,&mut ps);nvmlDeviceGetCurrentClocksThrottleReasons(d,&mut th);nvmlDeviceGetSupportedClocksThrottleReasons(d,&mut thsup);nvmlDeviceGetCurrPcieLinkGeneration(d,&mut pg);nvmlDeviceGetCurrPcieLinkWidth(d,&mut px);nvmlDeviceGetMaxPcieLinkGeneration(d,&mut pgm);nvmlDeviceGetMaxPcieLinkWidth(d,&mut pxm);nvmlDeviceGetPcieThroughput(d,0,&mut ptx);nvmlDeviceGetPcieThroughput(d,1,&mut prx);nvmlDeviceGetPcieReplayCounter(d,&mut replay);nvmlDeviceGetNumGpuCores(d,&mut cores);nvmlDeviceGetMemoryBusWidth(d,&mut bus);nvmlDeviceGetCudaComputeCapability(d,&mut ccmaj,&mut ccmin);nvmlDeviceGetArchitecture(d,&mut arch); let _=mem_range; } let tm=if field.nvmlReturn==OK {unsafe{field.value.uiVal as i64}} else {-1}; let hbm_status=field.nvmlReturn;out.push(format!("{{\"index\":{i},\"name\":\"{}\",\"uuid\":\"{}\",\"status\":{{\"hbmFieldNvmlReturn\":{hbm_status},\"hbmOffsetRangeReliability\":\"suspect_on_cmp\",\"gpcOffsetRangeReliability\":\"suspect_on_cmp\"}},\"offsets\":{{\"hbmRaw\":{mo},\"coreRaw\":{go},\"hbmRangeRaw\":[{mm},{mx}],\"coreRangeRaw\":[{gmin},{gmax}]}},\"clocksMHz\":{{\"graphics\":{c0},\"sm\":{c1},\"memory\":{c2},\"video\":{c3},\"maxGraphics\":{x0},\"maxSm\":{x1},\"maxMemoryStock\":{x2},\"maxVideo\":{x3}}},\"thermalC\":{{\"gpu\":{tg},\"hbm\":{tm},\"shutdown\":{tsh},\"slowdown\":{tsl},\"hbmMax\":{hm},\"gpuMax\":{tmax}}},\"power\":{{\"instantW\":{:.3},\"limitW\":{:.3},\"defaultLimitW\":{:.3},\"enforcedLimitW\":{:.3},\"minLimitW\":{:.3},\"maxLimitW\":{:.3},\"energyMilliJoules\":\"{}\"}},\"utilizationPct\":{{\"gpu\":{},\"memory\":{}}},\"memory\":{{\"vramUsedBytes\":\"{}\",\"vramFreeBytes\":\"{}\",\"vramTotalBytes\":\"{}\",\"bar1UsedBytes\":\"{}\",\"bar1FreeBytes\":\"{}\",\"bar1TotalBytes\":\"{}\"}},\"performance\":{{\"pstate\":{ps},\"throttleActiveMask\":{th},\"throttleSupportedMask\":{thsup}}},\"pcie\":{{\"currentGen\":{pg},\"currentWidth\":{px},\"maxGen\":{pgm},\"maxWidth\":{pxm},\"txKBps\":{ptx},\"rxKBps\":{prx},\"replayCounter\":{replay}}},\"static\":{{\"architectureEnum\":{arch},\"gpuCores\":{cores},\"memoryBusWidthBits\":{bus},\"cudaComputeCapability\":\"{ccmaj}.{ccmin}\"}}}}",strget(nvmlDeviceGetName,d),strget(nvmlDeviceGetUUID,d),pw as f64/1000.,pl as f64/1000.,pd as f64/1000.,pe as f64/1000.,plo as f64/1000.,phi as f64/1000.,energy,u.gpu,u.memory,m.used,m.free,m.total,b.used,b.free,b.total));} if json{println!("{{\"schemaVersion\":2,\"gpus\":[{}]}}",out.join(","))}else{for x in out{println!("{x}")}}
 } else { eprintln!("Usage: {} telemetry [--json] | fields | samples | processes | set-power-limit --uuid GPU-... --watts W [--apply] | set-core-offset|set-hbm-offset --uuid GPU-... --raw-offset N [--apply]",a[0]); }
 unsafe{nvmlShutdown()};
}
